rules.logic:
(function() {
  if (element.querySelector('.shopping-deals-carousel')) return;

  var ads = document.querySelectorAll('li.b_ad');
  if (!ads.length) return;

  // Build carousel container
  var carousel = document.createElement('div');
  carousel.className = 'shopping-deals-carousel';
  carousel.setAttribute('role', 'region');
  carousel.setAttribute('aria-label', 'Sponsored Shopping Deals');

  // Header
  var header = document.createElement('div');
  header.className = 'carousel-header';
  header.innerHTML = '<span class="carousel-icon">🛒</span><strong>Shopping Deals</strong><span class="carousel-badge">' + ads.length + ' Sponsored Offers</span>';
  carousel.appendChild(header);

  // Cards container
  var cardsContainer = document.createElement('div');
  cardsContainer.className = 'carousel-cards';

  ads.forEach(function(ad) {
    var linkEl = ad.querySelector('h2 a');
    var descEl = ad.querySelector('.b_ad_description');
    var domainEl = ad.querySelector('.b_domian');
    var calloutEl = ad.querySelector('.b_secondaryText.callout_vis');
    var faviconEl = ad.querySelector('.b_favicon img');

    if (!linkEl) return;

    var title = linkEl.textContent || '';
    var href = linkEl.getAttribute('href') || '#';
    var desc = '';
    if (descEl) {
      desc = descEl.cloneNode(true);
      var badge = desc.querySelector('.ta-slug-pos-wrapper, acf-badge');
      if (badge) badge.remove();
      desc = desc.textContent.trim();
    }
    var domain = domainEl ? domainEl.textContent.trim() : '';
    var callout = calloutEl ? calloutEl.textContent.trim() : '';
    var faviconSrc = faviconEl ? faviconEl.getAttribute('src') : '';

    // Parse callouts into chips
    var calloutChips = '';
    if (callout) {
      var items = callout.split(/\s*·\s*/).filter(function(s){return s.trim();});
      items.forEach(function(item) {
        calloutChips += '<span class="deal-chip">' + item.trim() + '</span>';
      });
    }

    var card = document.createElement('a');
    card.className = 'deal-card';
    card.href = href;
    card.target = '_blank';
    card.rel = 'noopener noreferrer';

    var iconHtml = '';
    if (faviconSrc) {
      iconHtml = '<div class="deal-favicon"><img src="' + faviconSrc + '" alt="" onerror="this.parentElement.style.display=\'none\'"/></div>';
    } else {
      iconHtml = '<div class="deal-favicon deal-favicon-placeholder">🏷️</div>';
    }

    card.innerHTML = iconHtml +
      '<div class="deal-domain">' + domain + '</div>' +
      '<div class="deal-title">' + title + '</div>' +
      '<div class="deal-desc">' + desc + '</div>' +
      (calloutChips ? '<div class="deal-callouts">' + calloutChips + '</div>' : '') +
      '<div class="deal-cta">View Deal →</div>';

    cardsContainer.appendChild(card);
  });

  carousel.appendChild(cardsContainer);

  // Styles
  var styleId = 'shopping-carousel-styles';
  if (!document.getElementById(styleId)) {
    var style = document.createElement('style');
    style.id = styleId;
    style.textContent = [
      '.shopping-deals-carousel {',
      '  background: linear-gradient(135deg, #fff8e1 0%, #ffecb3 50%, #ffe082 100%);',
      '  border: 2px solid #ff8f00;',
      '  border-radius: 12px;',
      '  margin: 0 0 16px 0;',
      '  padding: 16px 20px;',
      '  box-shadow: 0 4px 20px rgba(255,143,0,0.25);',
      '}',
      '.carousel-header {',
      '  display: flex;',
      '  align-items: center;',
      '  gap: 8px;',
      '  margin-bottom: 14px;',
      '  font-size: 18px;',
      '  color: #e65100;',
      '}',
      '.carousel-icon {',
      '  font-size: 24px;',
      '}',
      '.carousel-badge {',
      '  background: #ff6f00;',
      '  color: #fff;',
      '  font-size: 11px;',
      '  font-weight: 700;',
      '  padding: 2px 8px;',
      '  border-radius: 10px;',
      '  margin-left: 4px;',
      '}',
      '.carousel-cards {',
      '  display: flex;',
      '  gap: 16px;',
      '  overflow-x: auto;',
      '  padding-bottom: 8px;',
      '  scroll-behavior: smooth;',
      '}',
      '.carousel-cards::-webkit-scrollbar {',
      '  height: 6px;',
      '}',
      '.carousel-cards::-webkit-scrollbar-thumb {',
      '  background: #ffab40;',
      '  border-radius: 3px;',
      '}',
      '.deal-card {',
      '  flex: 0 0 280px;',
      '  background: #fff;',
      '  border: 1.5px solid #ffcc80;',
      '  border-radius: 10px;',
      '  padding: 14px;',
      '  text-decoration: none;',
      '  color: inherit;',
      '  display: flex;',
      '  flex-direction: column;',
      '  gap: 8px;',
      '  transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;',
      '}',
      '.deal-card:hover {',
      '  transform: translateY(-3px);',
      '  box-shadow: 0 6px 18px rgba(255,143,0,0.3);',
      '  border-color: #ff8f00;',
      '}',
      '.deal-favicon {',
      '  width: 32px;',
      '  height: 32px;',
      '  border-radius: 6px;',
      '  overflow: hidden;',
      '  background: #f5f5f5;',
      '  display: flex;',
      '  align-items: center;',
      '  justify-content: center;',
      '}',
      '.deal-favicon img {',
      '  width: 100%;',
      '  height: 100%;',
      '  object-fit: contain;',
      '}',
      '.deal-favicon-placeholder {',
      '  font-size: 18px;',
      '}',
      '.deal-domain {',
      '  font-size: 11px;',
      '  color: #888;',
      '  text-transform: uppercase;',
      '  letter-spacing: 0.5px;',
      '}',
      '.deal-title {',
      '  font-size: 14px;',
      '  font-weight: 700;',
      '  color: #212121;',
      '  line-height: 1.3;',
      '  display: -webkit-box;',
      '  -webkit-line-clamp: 2;',
      '  -webkit-box-orient: vertical;',
      '  overflow: hidden;',
      '}',
      '.deal-desc {',
      '  font-size: 12px;',
      '  color: #555;',
      '  line-height: 1.4;',
      '  display: -webkit-box;',
      '  -webkit-line-clamp: 2;',
      '  -webkit-box-orient: vertical;',
      '  overflow: hidden;',
      '}',
      '.deal-callouts {',
      '  display: flex;',
      '  flex-wrap: wrap;',
      '  gap: 4px;',
      '}',
      '.deal-chip {',
      '  background: #e8f5e9;',
      '  color: #2e7d32;',
      '  font-size: 10px;',
      '  font-weight: 600;',
      '  padding: 2px 7px;',
      '  border-radius: 4px;',
      '}',
      '.deal-cta {',
      '  margin-top: auto;',
      '  background: linear-gradient(90deg, #ff8f00, #ff6f00);',
      '  color: #fff;',
      '  text-align: center;',
      '  padding: 7px 12px;',
      '  border-radius: 6px;',
      '  font-size: 13px;',
      '  font-weight: 700;',
      '  letter-spacing: 0.3px;',
      '}',
    ].join('\n');
    document.head.appendChild(style);
  }

  // Insert carousel at the top of the main content, before b_results
  var results = element.querySelector('#b_results');
  if (results && element.contains(carousel)) {
    // Already inserted but check
  } else if (results) {
    element.insertBefore(carousel, results);
  } else {
    element.prepend(carousel);
  }
})();
